using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("build.binlog");

Console.WriteLine("=== BUILD RESULT ===");
Console.WriteLine($"Succeeded: {build.Succeeded}");
Console.WriteLine();

// Collect all errors
var errors = build.FindChildrenRecursive<Error>().ToList();
Console.WriteLine($"=== ALL ERRORS ({errors.Count}) ===");
foreach (var e in errors)
{
    var project = GetProject(e);
    Console.WriteLine($"[{project}] {e.Code}: {e.File}({e.LineNumber},{e.ColumnNumber}): {e.Text}");
}

Console.WriteLine();

// Collect all warnings
var warnings = build.FindChildrenRecursive<Warning>().ToList();
Console.WriteLine($"=== WARNINGS ({warnings.Count}) ===");
foreach (var w in warnings.Take(30))
{
    var project = GetProject(w);
    Console.WriteLine($"[{project}] {w.Code}: {w.Text}");
}
if (warnings.Count > 30) Console.WriteLine($"... and {warnings.Count - 30} more warnings");

Console.WriteLine();

// Show project build results
var projects = build.FindChildrenRecursive<Project>().ToList();
Console.WriteLine($"=== PROJECTS ({projects.Count}) ===");
foreach (var p in projects)
{
    var projErrors = p.FindChildrenRecursive<Error>().ToList();
    if (projErrors.Any())
    {
        Console.WriteLine($"FAILED: {p.Name} ({projErrors.Count} errors)");
    }
}

static string GetProject(BaseNode node)
{
    var current = node.Parent;
    while (current != null)
    {
        if (current is Project p) return p.Name;
        current = current.Parent;
    }
    return "unknown";
}
