using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("build.binlog");

// Get more details about the failed project
var projects = build.FindChildrenRecursive<Project>().ToList();
foreach (var p in projects)
{
    if (p.Name == "Services.csproj")
    {
        Console.WriteLine($"=== Project: {p.Name} ===");
        Console.WriteLine($"ProjectFile: {p.ProjectFile}");

        // Look for package references / items
        var items = p.FindChildrenRecursive<Item>().ToList();
        var pkgRefs = items.Where(i => i.Parent is Folder f && f.Name.Contains("PackageReference")).ToList();
        Console.WriteLine($"\nPackageReference items found: {pkgRefs.Count}");
        foreach (var pr in pkgRefs)
        {
            Console.WriteLine($"  - {pr.Name} {pr.Text}");
        }

        // Look for AddItem with PackageReference
        var addItems = p.FindChildrenRecursive<AddItem>().Where(a => a.Name.Contains("Package")).ToList();
        Console.WriteLine($"\nAddItem (Package*): {addItems.Count}");
        foreach (var ai in addItems)
        {
            Console.WriteLine($"  - {ai.Name}");
            foreach (var child in ai.Children)
            {
                Console.WriteLine($"    child: {child}");
            }
        }

        // Look for all targets that failed
        var targets = p.FindChildrenRecursive<Target>().Where(t => !t.Succeeded).ToList();
        Console.WriteLine($"\nFailed targets: {targets.Count}");
        foreach (var t in targets)
        {
            Console.WriteLine($"  - {t.Name}");
        }

        break;
    }
}

// Also check what other projects exist
Console.WriteLine("\n=== ALL PROJECT FILES ===");
foreach (var p in projects.Where(p => p.Name.EndsWith(".csproj")))
{
    var errs = p.FindChildrenRecursive<Error>().Count();
    Console.WriteLine($"  {p.Name} (errors: {errs}) - {p.ProjectFile}");
}
