using System;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("build.binlog");

// Extract source file contents from the binlog
var sourceFiles = build.FindChildrenRecursive<SourceFile>().ToList();
Console.WriteLine($"SourceFiles embedded: {sourceFiles.Count}");

// Look for the .csproj content and UserService.cs
var allFiles = build.FindChildrenRecursive<SourceFileLine>().ToList();
Console.WriteLine($"SourceFileLines: {allFiles.Count}");

// Try to find project evaluation data
var evals = build.FindChildrenRecursive<ProjectEvaluation>().ToList();
Console.WriteLine($"\n=== PROJECT EVALUATIONS ({evals.Count}) ===");
foreach (var eval in evals)
{
    Console.WriteLine($"  {eval.Name} - {eval.ProjectFile}");

    // Look for items
    var items = eval.FindChildrenRecursive<Item>().ToList();
    var pkgItems = items.Where(i => {
        var parent = i.Parent;
        while (parent != null)
        {
            if (parent is NamedNode nn && nn.Name.Contains("PackageReference"))
                return true;
            parent = parent.Parent;
        }
        return false;
    }).ToList();

    if (pkgItems.Any())
    {
        Console.WriteLine($"    PackageReference items:");
        foreach (var pi in pkgItems)
            Console.WriteLine($"      {pi.Name}");
    }

    // Look for all named nodes containing "Package"
    var packageNodes = eval.FindChildrenRecursive<NamedNode>()
        .Where(n => n.Name.Contains("Package"))
        .Take(10).ToList();
    if (packageNodes.Any())
    {
        Console.WriteLine($"    Nodes with 'Package' in name:");
        foreach (var pn in packageNodes)
            Console.WriteLine($"      [{pn.GetType().Name}] {pn.Name}: children={pn.Children.Count}");
    }
}
