                            Console.WriteLine($"      {gcn.Name}");
                    }
                }
            }
        }
    }
}

static void PrintTree(BaseNode node, int depth, int maxDepth)
{
    if (depth > maxDepth) return;
    var indent = new string(' ', depth * 2);
    var typeName = node.GetType().Name;
    string display = node switch
    {
        NamedNode nn => $"[{typeName}] {nn.Name}",
        _ => $"[{typeName}] {node}"
    };
    Console.WriteLine($"{indent}{display}");
    if (node is TreeNode tn)
    {
        foreach (var child in tn.Children)
        {
            if (child is BaseNode bn)
                PrintTree(bn, depth + 1, maxDepth);
        }
    }
}
